await t('second audit extends a guest who did not check out', async () => { const a = (await okOp('nightAudit', { date: addDays(D, 1) })).audit; assert.equal(a.extended.length, 2); assert.equal((await st()).res.find(r => r.id === wid).depart, addDays(D, 2)); });
