  assert.equal((await one(13)).status, 200); assert.equal((await one(11)).status, 200);   // bd+13 and bd+11 are less than 14 days away: released
  assert.equal((await op('groupSave', { id: gid, cutoffDays: 400 })).status, 400); assert.equal((await op('groupSave', { id: gid, cutoffDays: -1 })).status, 400); assert.equal((await op('groupSave', { id: gid, cutoffDays: 2.5 })).status, 400); assert.equal((await op('groupSave', { id: gid, cutoff: N(5), cutoffDays: 3 })).status, 400);
