  await okOp('groupSave', { id: g0, cutoff: N(-1) }); g = (await call('GET', '/group?id=' + g0)).json.group; assert.equal(g.cutoffDays, undefined); assert.equal(g.cutoff, N(-1)); assert.equal((await one(41)).status, 200);   // a fixed date that has passed: released
