await t('rewards earn by nights: two nights = 200 points; check-out undone takes exactly that back; checking out again earns once, never twice', async () => {
  const id = await rwWalk('Nighty', mem1, 2); let a = (await okOp('nightAudit', { date: (await st()).config.bdate })).audit; a = (await okOp('nightAudit', { date: (await st()).config.bdate })).audit; assert.equal((await folio(id)).lines.filter(l => l.code === 'RM').length, 2);
  await okOp('checkOut', { id, force: true }); const r = (await folio(id)).res; assert.deepEqual(r.rwEarned, { points: 200, nights: 2, revenue: 16000 }); let m = (await mState(mem1)).member; assert.deepEqual([m.points, m.earned, m.nights, m.revenue, m.stays], [200, 200, 2, 16000, 1]); assert.equal(m.log.at(-1).what, 'Stay ' + r.conf + ': +200 points'); assert.equal(m.log.at(-1).points, 200);
  assert.equal((await op('checkOut', { id, force: true })).status, 400); assert.equal((await mState(mem1)).member.points, 200);
  await okOp('undoCheckOut', { id }); m = (await mState(mem1)).member; assert.deepEqual([m.points, m.earned, m.nights, m.revenue, m.stays], [0, 0, 0, 0, 0]); assert.equal(m.log.at(-1).what, 'Check-out undone: −200 points'); assert.equal((await folio(id)).res.rwEarned, undefined);
  await okOp('checkOut', { id, force: true }); m = (await mState(mem1)).member; assert.deepEqual([m.points, m.stays], [200, 1]); });
