await t('rewards redeem: needs a member and the minimum, not more than the points or the balance; posts points x value as a payment; subtracts the points; redeemed points do not earn', async () => {
  const id = await rwWalk('Redeemer', mem1); await okOp('post', { res: id, kind: 'charge', code: 'RM', amount: 8000 }); assert.equal((await folio(id)).balance, 8819); const R = (pts, extra) => op('post', { res: id, kind: 'payment', code: 'RW', points: pts, ...extra });
  assert.equal((await op('post', { res: id, kind: 'charge', code: 'RW', points: 1000 })).status, 400); assert.equal((await R(999)).status, 400); assert.equal((await R(0)).status, 400); assert.equal((await R(1500.5)).status, 400); assert.equal((await R(9000)).status, 400); assert.equal((await R(13000)).status, 400); assert.equal((await folio(id)).balance, 8819); assert.equal((await mState(mem1)).member.points, 12005);
  const x = await okOp('post', { res: id, kind: 'payment', code: 'RW', points: 3000 }); assert.equal(x.balance, 5819); let f = await folio(id), l = f.lines.at(-1); assert.deepEqual([l.code, l.amount, l.comment, l.descr], ['RW', -3000, '3000 points, member R100001', 'Rewards Redemption']); let m = (await mState(mem1)).member; assert.deepEqual([m.points, m.earned], [9005, 2010]); assert.deepEqual([m.log.at(-1).what, m.log.at(-1).points], ['Redeemed 3000 points on ' + f.res.conf, -3000]);
  await okOp('configSave', { config: { rewards: { pointValue: 2 } } }); await okOp('post', { res: id, kind: 'payment', code: 'RW', points: 1000 }); f = await folio(id); assert.equal(f.lines.at(-1).amount, -2000); assert.equal(f.balance, 3819); assert.equal((await mState(mem1)).member.points, 8005); assert.equal((await R(2000)).status, 400);   // 2000 points = 40.00, more than the 38.19 balance
  await okOp('configSave', { config: { rewards: { pointValue: 0 } } }); assert.equal((await R(1000)).status, 400); await okOp('configSave', { config: { rewards: { pointValue: 1, minRedeem: 3000 } } }); assert.equal((await R(2999)).status, 400); await okOp('configSave', { config: { rewards: { minRedeem: 1000 } } });
  const nm = await rwWalk('Nomem', 0); await okOp('post', { res: nm, kind: 'charge', code: 'RM', amount: 8000 }); assert.equal((await op('post', { res: nm, kind: 'payment', code: 'RW', points: 1000 })).status, 400);
  await okOp('post', { res: id, kind: 'payment', code: 'CA', amount: 3819 }); await okOp('checkOut', { id }); m = (await mState(mem1)).member; assert.equal(m.points, 8005 + 100); assert.equal(m.earned, 2110);   // the stay earned 100 (nights mode) on the room charge only, not on the payment by points
  await okOp('configSave', { config: { rewards: { enabled: false } } }); assert.equal((await op('memberSave', { last: 'Late' })).status, 400); assert.deepEqual((await st()).members, []); assert.equal((await op('post', { res: nm, kind: 'payment', code: 'RW', points: 1000 })).status, 400); await okOp('configSave', { config: { rewards: { enabled: true } } }); assert.equal((await st()).members.length, 3); });
await t('cleaning schedules: a Traditional schedule exists, rooms use it, the list is checked', async () => {
  let s = await st(); assert.deepEqual(s.config.cleanSchedules, [{ id: 'trad', name: 'Traditional', days: ['F', 'F', 'F', 'F', 'F', 'F', 'F'] }]); assert.ok(s.config.rooms.every(r => r.sched === 'trad'));
  const base = s.config.cleanSchedules[0];
  for (const bad of [[], [{ name: '', days: ['F'] }], [{ name: 'X', days: [] }], [{ name: 'X', days: Array(15).fill('F') }], [{ name: 'X', days: ['Q'] }], [base, { name: 'traditional', days: ['F'] }]]) assert.equal((await op('configSave', { config: { cleanSchedules: bad } })).status, 400);
  await okOp('configSave', { config: { cleanSchedules: [base, { name: 'Eco', days: ['F', 'N', 'L', 'N', 'F', 'N', 'N', 'L', 'N', 'N'] }] } }); s = await st(); assert.equal(s.config.cleanSchedules.length, 2); assert.equal(s.config.cleanSchedules[1].days.length, 10); const eco = s.config.cleanSchedules[1].id; assert.ok(eco && eco !== 'trad');
  assert.equal((await op('configSave', { config: { rooms: s.config.rooms.map(r => r.no === '101' ? { ...r, sched: 'nope' } : r) } })).status, 400);
  await okOp('configSave', { config: { rooms: s.config.rooms.map(r => r.no === '101' ? { ...r, sched: eco } : r) } }); s = await st(); assert.equal(s.config.rooms.find(r => r.no === '101').sched, eco); assert.equal(s.config.rooms.find(r => r.no === '102').sched, 'trad');
  const gone = await op('configSave', { config: { cleanSchedules: [base] } }); assert.equal(gone.status, 400); assert.match(gone.json.error, /"Eco" is still used by room 101/);
  await okOp('configSave', { config: { rooms: s.config.rooms, cleanSchedules: s.config.cleanSchedules } });   // the same list again is fine
  await okOp('configSave', { config: { rooms: s.config.rooms.map(r => ({ ...r, sched: 'trad' })), cleanSchedules: [base] } }); s = await st(); assert.equal(s.config.cleanSchedules.length, 1);
  assert.equal((await op('configSave', { config: { cleanSchedules: [{ name: 'Only', days: ['F'] }] } }, { cookie: desk })).status, 403); });
