await t('work orders: housekeeping opens one, only the desk can take the room out of order, done puts it back', async () => {
  const mk = await ok('/account/userSave', { email: 'maid@alpha.com', name: 'May Maid', role: 'hk', disabled: false }); const lg = await call('POST', '/auth/login', { email: 'maid@alpha.com', password: 'maidpassword2' }, { keep: true }); assert.equal(lg.status, 200); const maid = lg.token;
  assert.equal((await op('woAdd', { room: '999', reason: 'Plumbing' }, { cookie: maid })).status, 400); assert.equal((await op('woAdd', { room: '105', reason: 'Mini fridge' }, { cookie: maid })).status, 400); assert.equal((await op('woAdd', { room: '105', reason: 'Drapes' }, { cookie: maid })).status, 400);
  assert.equal((await op('woAdd', { room: '105', reason: 'plumbing', notes: 'Sink drips', ooo: { start: D, end: addDays(D, 2) } }, { cookie: maid })).status, 403);
  const w1 = (await ok('/op', { op: 'woAdd', a: { room: '105', reason: 'plumbing', notes: 'Sink drips' } }, { cookie: maid })).json; assert.ok(w1.id); assert.equal(w1.blockId, null);
  let s = await st(maid); const w = s.workorders.find(x => x.id === w1.id); assert.deepEqual([w.room, w.reason, w.notes, w.status, w.createdBy, w.bdate], ['105', 'Plumbing', 'Sink drips', 'open', 'May Maid', s.config.bdate]);
  const blocksBefore = (await st()).blocks.length;
  const w2 = await okOp('woAdd', { room: '106', reason: 'Door Lock', notes: 'Key card fails', ooo: { start: D, end: addDays(D, 2) } }); assert.ok(w2.blockId); s = await st(); assert.equal(s.blocks.length, blocksBefore + 1); assert.equal(s.blocks.find(b => b.id === w2.blockId).room, '106');
  assert.equal((await op('woAdd', { room: '102', reason: 'Plumbing', ooo: { start: D, end: D } })).status, 409);   // a guest is in 102
  assert.equal((await op('woDone', { id: w2.id, putBack: true }, { cookie: maid })).status, 403); assert.equal((await op('woDone', { id: 99999 })).status, 404);
  assert.equal((await op('woDone', { id: w1.id }, { cookie: maid })).status, 200); assert.equal((await op('woDone', { id: w1.id })).status, 400);
  const d2 = await okOp('woDone', { id: w2.id, putBack: true }); assert.equal(d2.backInOrder, true); s = await st(); assert.equal(s.blocks.length, blocksBefore); const done = s.workorders.find(x => x.id === w2.id); assert.equal(done.status, 'done'); assert.ok(done.doneAt); assert.equal(done.doneBy.length > 0, true);
  const w3 = await okOp('woAdd', { room: '107', reason: 'Door Lock' }); assert.equal((await st()).workorders.filter(x => x.status === 'open').length, 1); assert.equal((await st(maid)).workorders.length, 3); });
